+// We are using the native dialog command API, but including JS fallback for older browsers
+// and handling the custom logic if needed.
+
+document.addEventListener('DOMContentLoaded', () => {
+  const dialog = document.getElementById('delete-dialog');
+  const trigger = document.querySelector('.trigger');
+  
+  // Check if browser supports command/commandfor attributes natively.
+  // If not, we set up JS event listeners as a fallback.
+  if (!('command' in HTMLButtonElement.prototype)) {
+    trigger.addEventListener('click', () => {
+      dialog.showModal();
+    });
+
+    const closeButtons = dialog.querySelectorAll('[command="close"]');
+    closeButtons.forEach(btn => {
+      btn.addEventListener('click', () => {
+        dialog.close(btn.value || '');
+      });
+    });
+  }
+
+  // Handle the close event for custom logic (e.g., actually deleting the image)
+  dialog.addEventListener('close', () => {
+    if (dialog.returnValue === 'delete') {
+      console.log('Image deleted');
+      // In a real app, you would make an API call here and then update the UI
+      const imageCard = trigger.closest('.image-card');
+      if (imageCard) {
+        imageCard.remove();
+      }
+    }
+    
+    // The browser restores focus to the trigger automatically for native dialogs.
+    // However, if the trigger is removed (like we just did), focus is lost.
+    // We need to manage focus manually in this case.
+    if (!document.contains(trigger)) {
+      // Move focus to a logical element, e.g., the main heading
+      const mainHeading = document.querySelector('h1');
+      if (mainHeading) {
+        mainHeading.tabIndex = -1; // make it programmatically focusable
+        mainHeading.focus();
+      }
+    }
+  });
+});
