  <script type="text/babel">
    const { useState, useRef, useEffect } = React;

    function App() {
      const [isDialogOpen, setIsDialogOpen] = useState(false);
      const [imageDeleted, setImageDeleted] = useState(false);
      const triggerRef = useRef(null);
      const dialogRef = useRef(null);
      const headingRef = useRef(null);

      // Manage dialog open state via native API when prop changes
      useEffect(() => {
        const dialog = dialogRef.current;
        if (!dialog) return;

        if (isDialogOpen && !dialog.open) {
          dialog.showModal();
        } else if (!isDialogOpen && dialog.open) {
          dialog.close();
        }
      }, [isDialogOpen]);

      // Handle native close events (e.g., via Escape key)
      useEffect(() => {
        const dialog = dialogRef.current;
        if (!dialog) return;

        const handleClose = () => {
          setIsDialogOpen(false);
          // If the action was delete, set state
          if (dialog.returnValue === 'delete') {
            setImageDeleted(true);
          }

          // Focus management: if image is deleted, trigger is gone. Focus heading.
          if (dialog.returnValue === 'delete' && headingRef.current) {
            headingRef.current.focus();
          } else if (dialog.returnValue !== 'delete' && triggerRef.current) {
             triggerRef.current.focus();
          }
        };

        dialog.addEventListener('close', handleClose);
        return () => dialog.removeEventListener('close', handleClose);
      }, []);

      const handleDeleteClick = () => {
        setIsDialogOpen(true);
      };

      const handleDialogClose = (action) => {
        const dialog = dialogRef.current;
        if (dialog) {
          dialog.returnValue = action;
          dialog.close();
        }
      };

      return (
        <React.Fragment>
          <header>
            <h1 ref={headingRef} tabIndex={-1}>Image Library</h1>
          </header>

          <main>
            {!imageDeleted ? (
              <div className="image-card">
                <img src="https://picsum.photos/400/300" alt="Random landscape" />
                <div className="actions">
                  <button 
                    type="button" 
                    className="trigger" 
                    onClick={handleDeleteClick}
                    ref={triggerRef}
                  >
                    Delete Image
                  </button>
                </div>
              </div>
            ) : (
               <p role="status">Image has been deleted.</p>
            )}
          </main>

          <dialog 
            ref={dialogRef} 
            id="delete-dialog" 
            aria-labelledby="dialog-title" 
            aria-describedby="dialog-desc"
          >
            <div className="dialog-content">
              <h2 id="dialog-title">Delete this image?</h2>
              <p id="dialog-desc">Are you sure you want to remove this image from your library? This action cannot be undone.</p>

              <div className="dialog-actions">
                <button 
                  type="button" 
                  className="btn-cancel" 
                  onClick={() => handleDialogClose('cancel')}
                  autoFocus
                >
                  Cancel
                </button>
                <button 
                  type="button" 
                  className="btn-danger" 
                  onClick={() => handleDialogClose('delete')}
                >
                  Delete
                </button>
              </div>
            </div>
          </dialog>
        </React.Fragment>
      );
    }

    const root = ReactDOM.createRoot(document.getElementById('root'));
    root.render(<App />);
  </script>
</body>
